create index attendance_sessions_school_date_idx on public.attendance_sessions(school_id,attendance_date);
create index attendance_sessions_school_period_idx on public.attendance_sessions(school_id,academic_year_id,term_id);
create table public.attendance_records (id integer generated by default as identity primary key, school_id integer not null references public.schools(id) on delete cascade, attendance_session_id integer not null, student_id integer not null, status varchar(12) not null, remarks varchar(255) null, created_at timestamp without time zone null, updated_at timestamp without time zone null, constraint attendance_record_student_unique unique(school_id,attendance_session_id,student_id), foreign key(school_id,attendance_session_id) references public.attendance_sessions(school_id,id) on delete cascade, foreign key(school_id,student_id) references public.student_records(school_id,user_id) match full on delete cascade, constraint attendance_record_student_user_legacy_fk foreign key(student_id) references public.users(id) on delete cascade);
create table public.audit_logs (id bigint generated by default as identity primary key, school_id integer null references public.schools(id) on delete set null, actor_id integer null references public.users(id) on delete set null, action varchar(100) not null, auditable_type varchar(255) null, auditable_id bigint null, description varchar(255) null, properties jsonb null, ip_address varchar(45) null, user_agent varchar(255) null, created_at timestamp without time zone null, updated_at timestamp without time zone null);
create index audit_logs_school_created_idx on public.audit_logs(school_id,created_at);
create index audit_logs_actor_created_idx on public.audit_logs(actor_id,created_at);

create or replace function private.check_audit_actor_school() returns trigger
language plpgsql security definer set search_path = '' set row_security = off as $$
declare actor_school integer; actor_type text;
begin
  if new.actor_id is null then return new; end if;
  select u.school_id, u.user_type into actor_school, actor_type from public.users u where u.id = new.actor_id;
  if not found then raise exception 'audit actor does not exist'; end if;
  if actor_type = 'super_admin' then return new; end if;
  if actor_school is null or new.school_id is distinct from actor_school then
    raise exception 'audit actor school does not match audit school';
  end if;
  return new;
end
$$;
revoke all on function private.check_audit_actor_school() from public, anon, authenticated;
create trigger audit_logs_actor_school_guard before insert on public.audit_logs for each row execute function private.check_audit_actor_school();

create table public.roles (id integer generated by default as identity primary key, name varchar(50) not null unique, label varchar(100) not null, scope varchar(20) not null, created_at timestamp without time zone null, updated_at timestamp without time zone null);
create table public.permissions (id integer generated by default as identity primary key, name varchar(100) not null unique, description varchar(255) not null, created_at timestamp without time zone null, updated_at timestamp without time zone null);
create table public.role_permissions (role_id integer not null references public.roles(id) on delete cascade, permission_id integer not null references public.permissions(id) on delete cascade, primary key(role_id,permission_id));
create table public.user_permissions (id integer generated by default as identity primary key, user_id integer not null references public.users(id) on delete cascade, permission_id integer not null references public.permissions(id) on delete cascade, granted_by integer null references public.users(id) on delete set null, allowed boolean not null default true, created_at timestamp without time zone null, updated_at timestamp without time zone null, unique(user_id,permission_id));

do $$ declare t text; begin
 foreach t in array array[
  'users','class_types','my_classes','sections','subjects','student_records','exams','marks',
  'exam_records','grades','dorms','pins','books','book_requests','staff_records','payments',
  'payment_records','receipts','time_table_records','time_slots','time_tables','promotions','settings','skills'
 ] loop execute format('create index %I on public.%I (school_id)', t || '_school_id_index', t); end loop;
end $$;
