create index payments_academic_year_id_index on public.payments(academic_year_id);
create index payments_term_id_index on public.payments(term_id);
create index payment_records_academic_year_id_index on public.payment_records(academic_year_id);
create index payment_records_term_id_index on public.payment_records(term_id);
create index receipts_academic_year_id_index on public.receipts(academic_year_id);
