create or replace function private.current_profile_id() returns integer
language sql stable security definer set search_path = '' set row_security = off as $$
 select u.id from public.users u where u.auth_user_id = auth.uid() limit 1
$$;
create or replace function private.current_school_id() returns integer
language sql stable security definer set search_path = '' set row_security = off as $$
 select u.school_id from public.users u join public.schools s on s.id = u.school_id
 where u.auth_user_id = auth.uid() and u.school_id is not null and s.status in ('active', 'trial') limit 1
$$;
create or replace function private.has_permission(permission_name text) returns boolean
language sql stable security definer set search_path = '' set row_security = off as $$
 select coalesce((
   select up.allowed from public.user_permissions up
   join public.users u on u.id = up.user_id join public.permissions p on p.id = up.permission_id
   where u.auth_user_id = auth.uid()
     and ((u.user_type = 'super_admin') = (permission_name like 'platform.%'))
     and p.name = permission_name limit 1
 ), exists (
   select 1 from public.users u join public.roles r on r.name = u.user_type
   join public.role_permissions rp on rp.role_id = r.id join public.permissions p on p.id = rp.permission_id
   where u.auth_user_id = auth.uid()
     and ((u.user_type = 'super_admin') = (permission_name like 'platform.%'))
     and p.name = permission_name
 ))
$$;
revoke all on function private.current_profile_id() from public, anon, authenticated;
revoke all on function private.current_school_id() from public, anon, authenticated;
revoke all on function private.has_permission(text) from public, anon, authenticated;
grant usage on schema private to authenticated;
grant execute on function private.current_profile_id() to authenticated;
grant execute on function private.current_school_id() to authenticated;
grant execute on function private.has_permission(text) to authenticated;

do $$ declare t text; begin
 foreach t in array array[
  'blood_groups','states','lgas','nationalities','users','password_resets','user_types',
  'class_types','my_classes','sections','settings','subjects','student_records','dorms',
  'exams','marks','grades','pins','skills','exam_records','books','book_requests','staff_records',
  'payments','payment_records','receipts','time_table_records','time_slots','time_tables','promotions',
  'schools','academic_years','terms','attendance_sessions','attendance_records','audit_logs',
  'roles','permissions','role_permissions','user_permissions'
 ] loop
   execute format('alter table public.%I enable row level security', t);
   execute format('alter table public.%I force row level security', t);
   execute format('revoke all on table public.%I from public, anon, authenticated', t);
 end loop;
end $$;

